{
  "bioavailability_prediction": "high",
  "confidence": "low",
  "revision_action": "keep",
  "supportive_card_ids": ["C10","C12","C13","C23","C37","C43","C44","C45","C48","C50","C120"],
  "contradictory_card_ids": ["C267","C256","C245","C237","C247"],
  "prediction_basis_card_ids": ["C10","C12","C23","C43","C50"],
  "claims": [
    {
      "claim": "L1 rosuvastatin records report an absolute oral bioavailability of approximately 20% in humans, meeting the F >= 20% threshold.",
      "card_ids": ["C10","C12","C13","C23","C37","C43","C44","C45","C48","C50"]
    },
    {
      "claim": "L2 rosuvastatin records consistently report ~20% F and indicate absorption exceeds F because of first-pass loss; no below-threshold value is provided.",
      "card_ids": ["C65","C70","C88","C95","C102","C110","C111","C120"]
    },
    {
      "claim": "L5 records characterize rosuvastatin as a BCRP/ABCG2 substrate whose gut-wall efflux limits absorption, but they are rosuvastatin-specific and do not measure atorvastatin F.",
      "card_ids": ["C232","C245","C247","C267","C256","C237"]
    },
    {
      "claim": "Rosuvastatin F remains ~20% despite substantial gut-wall efflux, so L5 mechanism alone does not affirmatively establish F < 20% for the query.",
      "card_ids": ["C10","C267","C256","C245"]
    },
    {
      "claim": "No L5 record provides direct or threshold-relevant evidence for atorvastatin F < 20%; structural differences (pyrrole carboxamide vs pyrimidine sulfonamide, higher lipophilicity) limit transfer.",
      "card_ids": ["C267","C256","C245","C237"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "low",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C232","C245","C247","C267","C256","C237","C273","C280","C281","C249","C260","C277"]
    }
  ],
  "evidence_gaps": [
    "No direct atorvastatin absolute oral bioavailability measurement is present in any L1-L5 card.",
    "L5 records are rosuvastatin-specific; transfer to atorvastatin is limited by structural and metabolic differences.",
    "Rosuvastatin F ~20% sits at the threshold, and gut-wall efflux evidence does not quantify atorvastatin's F.",
    "No atorvastatin-specific gut-wall efflux, intestinal metabolism, or first-pass data are available.",
    "Physicochemical liabilities alone are not affirmative low-F evidence."
  ],
  "decision_summary": "L5 adds rosuvastatin gut-wall efflux/BCRP evidence, but no atorvastatin-specific measurement. Rosuvastatin F ~20% meets the threshold despite efflux; mechanism alone is not affirmative evidence for atorvastatin F<20%. Prediction remains high with low confidence."
}

